controls.QUANTUM_WAVE_INTERFERENCE/a11y.detectorP:
{ $envelope ->
  [clusteringIntoTwoFaintSections] Taller bars at regular intervals are grouped into two close areas.
  [clusteringIntoTwoDistinctSections] Taller bars at regular intervals are grouped into two distinct areas.
  *[brightestAtCenter] Taller bars at regular intervals, with shorter bars between them. { $spatialDescription }
}

controls.QUANTUM_WAVE_INTERFERENCE/a11y.detectorS:
{ $sourceState ->
  [emittingPlaying] Data cleared. Hits detection restarted.
  [emittingPaused] { a11y_eraserResponses_dataClearedPaused }
  [offWithData] { a11y_eraserResponses_dataClearedSourceOff }
  *[offNoData] { a11y_eraserResponses_noCollectedData }
}

controls.QUANTUM_WAVE_INTERFERENCE/a11y.graphAcco:
{ $detectionMode ->
  [intensity] Dynamic graph of intensity data shown. { $graphState }
  *[hits] Dynamic histogram of hits data shown. { $graphState }
}

controls.QUANTUM_WAVE_INTERFERENCE/a11y.screenSum:
{ $experimentStatus ->
  [pausedMaxHits] Currently, sim is paused. Source is off. { maximumHitsReached }. Detector screen shows hits data.
  [pausedEmitting] Currently, sim is paused. Source emits { a11y_particleNouns_lowercasePlural } directly at double-slit barrier with { a11y_experimentStateClauses_slitConfiguration }. { a11y_experimentStateClauses_detectionResult }
  [pausedSourceOff] Currently, sim is paused. Source is off. { a11y_experimentStateClauses_detectionResult }
  [maxHits] Currently, source is off. { maximumHitsReached }. Detector screen shows hits data.
  [emitting] Currently, source emits { a11y_particleNouns_lowercasePlural } directly at double-slit barrier with { a11y_experimentStateClauses_slitConfiguration }. { a11y_experimentStateClauses_detectionResult }
  *[sourceOff] Currently, source is off. { a11y_experimentStateClauses_detectionResult }
}

controls.QUANTUM_WAVE_INTERFERENCE/a11y.singlePar:
{ $waveDisplayMode ->
  [amplitude] { $patternKind ->
                [doubleSlitInterference] For each wave packet, solid circular waves emerge from both slits and overlap.
                [singleSlitDiffraction] For each wave packet, a solid circular wave emerges from the open slit only.
                [whichPathDiffraction] For each wave packet, as detection events occur, solid circular waves emerge from both slits one at a time and do not interact.
                *[noBarrier] For each wave packet, a solid wave moves directly toward { a11y_waveExperimentResponses_waveProgressTarget }
              }
  [realPart] { $patternKind ->
               [doubleSlitInterference] For each wave packet, circular wave fronts emerge from both slits and overlap.
               [singleSlitDiffraction] For each wave packet, circular wave fronts emerge from the open slit only.
               [whichPathDiffraction] For each wave packet, as detection events occur, circular wave fronts emerge from both slits one at a time and do not interact.
               *[noBarrier] For each wave packet, plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
             }
  *[electricField] { $patternKind ->
                     [doubleSlitInterference] For each wave packet, circular wave fronts emerge from both slits and overlap.
                     [singleSlitDiffraction] For each wave packet, circular wave fronts emerge from the open slit only.
                     [whichPathDiffraction] For each wave packet, as detection events occur, circular wave fronts emerge from both slits one at a time and do not interact.
                     *[noBarrier] For each wave packet, plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                   }
}

{ $waveDisplayMode ->
  [amplitude] One after another, solid { a11y_sourceWaveFragments_lowercaseColor } wave packets move toward { a11y_sourceWaveFragments_slitTarget }
  [realPart] One after another, { a11y_sourceWaveFragments_lowercaseColorAndBlack } wave packets move toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
  *[electricField] One after another, { a11y_sourceWaveFragments_lowercaseColorAndBlack } wave packets move toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
}

{ $waveDisplayMode ->
  [amplitude] A single solid { a11y_sourceWaveFragments_lowercaseColor } { a11y_sourceWaveFragments_wavePacketType } wave packet moves toward { a11y_sourceWaveFragments_slitTarget }
  [realPart] A single { a11y_sourceWaveFragments_lowercaseColorAndBlack } { a11y_sourceWaveFragments_wavePacketType } wave packet moves toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
  *[electricField] A single { a11y_sourceWaveFragments_lowercaseColorAndBlack } { a11y_sourceWaveFragments_wavePacketType } wave packet moves toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
}

controls.QUANTUM_WAVE_INTERFERENCE/a11y.waveExper:
{ $displayMode ->
  [graph] Graph shown. { $surfaceState }
  *[screen] Detector screen shown. { $surfaceState }
}

{ $sourceState ->
  [emittingPlaying] Data cleared. Wave restarted.
  [emittingPaused] { a11y_eraserResponses_dataClearedPaused }
  [offWithData] { a11y_eraserResponses_dataClearedSourceOff }
  *[offNoData] { a11y_eraserResponses_noCollectedData }
}

{ $sourceState ->
  [emittingPlaying] Data cleared. Wave packets restarted.
  [emittingPaused] { a11y_eraserResponses_dataClearedPaused }
  [offWithData] { a11y_eraserResponses_dataClearedSourceOff }
  *[offNoData] { a11y_eraserResponses_noCollectedData }
}

{ $waveProgressStage ->
  [sourceOff] Source is off, so no wave is traveling.
  [atSlits] { $waveDisplayMode ->
              [amplitude] { $patternKind ->
                            [doubleSlitInterference] Solid circular waves emerge from both slits and overlap.
                            [singleSlitDiffraction] Solid circular wave emerges from open slit only.
                            [whichPathDiffraction] As detection events occur, solid circular waves emerge from both slits one at a time and do not interact.
                            *[noBarrier] Solid wave moves directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                          }
              [realPart] { $patternKind ->
                           [doubleSlitInterference] Circular wave fronts emerge from both slits and overlap.
                           [singleSlitDiffraction] Circular wave fronts emerge from open slit only.
                           [whichPathDiffraction] As detection events occur, circular wave fronts emerge from both slits one at a time and do not interact.
                           *[noBarrier] Plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                         }
              *[electricField] { $patternKind ->
                                 [doubleSlitInterference] Circular wave fronts emerge from both slits and overlap.
                                 [singleSlitDiffraction] Circular wave fronts emerge from open slit only.
                                 [whichPathDiffraction] As detection events occur, circular wave fronts emerge from both slits one at a time and do not interact.
                                 *[noBarrier] Plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                               }
            }
  [interferingAfterSlits] { $waveDisplayMode ->
                            [amplitude] Overlapping solid circular waves add and cancel, and spread fan-shaped rays toward { a11y_waveExperimentResponses_waveProgressTarget }
                            [realPart] Overlapping circular wave fronts add and cancel, and spread checkered pattern toward { a11y_waveExperimentResponses_waveProgressTarget }
                            *[electricField] Overlapping circular wave fronts add and cancel, and spread checkered pattern toward { a11y_waveExperimentResponses_waveProgressTarget }
                          }
  [diffractingAfterSlits] { $waveDisplayMode ->
                            [amplitude] Solid circular wave spreads toward { a11y_waveExperimentResponses_waveProgressTarget }
                            [realPart] Circular wave fronts spread toward { a11y_waveExperimentResponses_waveProgressTarget }
                            *[electricField] Circular wave fronts spread toward { a11y_waveExperimentResponses_waveProgressTarget }
                          }
  [whichPathAfterSlits] { $waveDisplayMode ->
                          [amplitude] Non-interacting solid circular waves spread toward { a11y_waveExperimentResponses_waveProgressTarget }
                          [realPart] Non-interacting circular wave fronts spread toward { a11y_waveExperimentResponses_waveProgressTarget }
                          *[electricField] Non-interacting circular wave fronts spread toward { a11y_waveExperimentResponses_waveProgressTarget }
                        }
  *[directToScreen] { $waveDisplayMode ->
                      [amplitude] Solid wave moves directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                      [realPart] Plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                      *[electricField] Plane wave fronts move directly toward { a11y_waveExperimentResponses_waveProgressTarget }
                    }
}

{ $sourceState ->
  [sourceOff] No beam is visible in wave area.
  *[sourceOn] { $waveDisplayMode ->
                [amplitude] Solid { a11y_sourceWaveFragments_lowercaseColor } wave moves toward { a11y_sourceWaveFragments_slitTarget }
                [realPart] { a11y_sourceWaveFragments_capitalizedColorAndBlack } plane wave fronts move toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
                *[electricField] { a11y_sourceWaveFragments_capitalizedColorAndBlack } plane wave fronts move toward { a11y_sourceWaveFragments_slitTarget } { a11y_sourceWaveFragments_wavePeakSpacing }
              }
}
